// StyleFromRefinement converts a refinement into Style, using zero values for unset fields.
func StyleFromRefinement(value StyleRefinement) Style {
	return Style{
		Display:               value.Display.UnwrapOrDefault(),
		Visibility:            value.Visibility.UnwrapOrDefault(),
		Overflow:              PointOfFromRefinement(value.Overflow),
		ScrollbarWidth:        value.ScrollbarWidth.UnwrapOrDefault(),
		AllowConcurrentScroll: value.AllowConcurrentScroll.UnwrapOrDefault(),
		RestrictScrollToAxis:  value.RestrictScrollToAxis.UnwrapOrDefault(),
		Position:              value.Position.UnwrapOrDefault(),
		Inset:                 EdgesOfFromRefinement(value.Inset),
		Size:                  SizeOfFromRefinement(value.Size),
		MinSize:               SizeOfFromRefinement(value.MinSize),
		MaxSize:               SizeOfFromRefinement(value.MaxSize),
		AspectRatio:           value.AspectRatio,
		Margin:                EdgesOfFromRefinement(value.Margin),
		Padding:               EdgesOfFromRefinement(value.Padding),
		BorderWidths:          EdgesOfFromRefinement(value.BorderWidths),
		AlignItems:            value.AlignItems,
		AlignSelf:             value.AlignSelf,
		AlignContent:          value.AlignContent,
		JustifyContent:        value.JustifyContent,
		Gap:                   SizeOfFromRefinement(value.Gap),
		FlexDirection:         value.FlexDirection.UnwrapOrDefault(),
		FlexWrap:              value.FlexWrap.UnwrapOrDefault(),
		FlexBasis:             value.FlexBasis.UnwrapOrDefault(),
		FlexGrow:              value.FlexGrow.UnwrapOrDefault(),
		FlexShrink:            value.FlexShrink.UnwrapOrDefault(),
		Background:            value.Background,
		BorderColor:           value.BorderColor,
		BorderStyle:           value.BorderStyle.UnwrapOrDefault(),
		CornerRadii:           CornersOfFromRefinement(value.CornerRadii),
		BoxShadow:             value.BoxShadow.UnwrapOrDefault(),
		Text:                  value.Text,
		MouseCursor:           value.MouseCursor,
		Opacity:               value.Opacity,
		GridCols:              value.GridCols,
		GridRows:              value.GridRows,
		GridLocation:          value.GridLocation,
		Debug:                 value.Debug.UnwrapOrDefault(),
		DebugBelow:            value.DebugBelow.UnwrapOrDefault(),
	}
}

